LT='M243 360 L243 208.75 A118.75 118.75 0 0 1 480 208.75 L480 445 L437 408 L437 208.75 A74.75 74.75 0 0 0 287 208.75 L287 325 Z'
def sk(x,y,s=1,ex='n',arm=None,glow=True,rot=0):
    star='M0 -50 C8 -14 14 -8 50 0 C14 8 8 14 0 50 C-8 14 -14 8 -50 0 C-14 -8 -8 -14 0 -50Z'
    o=f'<g transform="translate({x} {y}) rotate({rot}) scale({s})">'
    if glow:o+=f'<circle r="92" fill="{GD}" opacity=".14"/><circle r="64" fill="{GD}" opacity=".2"/>'
    o+=f'<path d="{star}" fill="{GD}"/><path d="{star}" fill="{GL}" transform="scale(.62)"/>'
    eyes={'n':f'<circle cx="-10" cy="-3" r="5.4" fill="{NV}"/><circle cx="10" cy="-3" r="5.4" fill="{NV}"/>','b':f'<path d="M-15 -3 h10 M5 -3 h10" stroke="{NV}" stroke-width="3.5" stroke-linecap="round"/>','h':f'<path d="M-15 0 q5 -8 10 0 M5 0 q5 -8 10 0" stroke="{NV}" stroke-width="3.5" fill="none" stroke-linecap="round"/>','w':f'<circle cx="-10" cy="-3" r="7.5" fill="{NV}"/><circle cx="10" cy="-3" r="7.5" fill="{NV}"/><circle cx="-8" cy="-6" r="2.6" fill="#fff"/><circle cx="12" cy="-6" r="2.6" fill="#fff"/>','s':f'<path d="M-15 -2 h10 M5 -2 h10" stroke="{NV}" stroke-width="3.5" stroke-linecap="round"/>'}[ex]
    mouth={'n':f'<path d="M-7 9 q7 7 14 0" stroke="{NV}" stroke-width="3.2" fill="none" stroke-linecap="round"/>','b':f'<path d="M-6 9 q6 5 12 0" stroke="{NV}" stroke-width="3" fill="none" stroke-linecap="round"/>','h':f'<path d="M-9 8 q9 11 18 0Z" fill="{NV}"/>','w':f'<ellipse cx="0" cy="11" rx="5" ry="6" fill="{NV}"/>','s':f'<path d="M-7 12 q7 -5 14 0" stroke="{NV}" stroke-width="3.2" fill="none" stroke-linecap="round"/>'}[ex]
    o+=eyes+mouth
    if arm=='wave':o+=f'<path d="M38 4 L70 -26" stroke="{GD}" stroke-width="11" stroke-linecap="round"/><circle cx="74" cy="-30" r="11" fill="{GD}"/><circle cx="74" cy="-30" r="11" fill="{GL}" opacity=".5"/>'
    if arm=='up':o+=f'<path d="M38 8 L66 -2" stroke="{GD}" stroke-width="11" stroke-linecap="round"/><circle cx="70" cy="-4" r="12" fill="{GD}"/><rect x="64" y="-30" width="12" height="22" rx="6" fill="{GD}"/>'
    if arm=='shrug':o+=f'<path d="M-38 6 L-66 -8 M38 6 L66 -8" stroke="{GD}" stroke-width="11" stroke-linecap="round"/><circle cx="-70" cy="-10" r="11" fill="{GD}"/><circle cx="70" cy="-10" r="11" fill="{GD}"/>'
    return o+'</g>'
def fr(inner,bg=NV,edge=None,lab=None):
    e=''
    if edge=='u':e=f'<rect x="200" y="0" width="240" height="6" rx="3" fill="{GD}"/><path d="M320 14 l22 28 h-44Z" fill="{GD}"/>'
    if edge=='r':e=f'<rect x="634" y="110" width="6" height="140" rx="3" fill="{GD}"/><path d="M612 180 l-28 22 v-44Z" fill="{GD}"/>'
    if edge=='d':e=f'<rect x="200" y="354" width="240" height="6" rx="3" fill="{GD}"/><path d="M320 346 l22 -28 h-44Z" fill="{GD}"/>'
    l=''
    if lab:
        pos={'u':'x="320" y="64"','r':'x="560" y="196"','d':'x="320" y="312"'}[edge]
        l=f'<text {pos} text-anchor="middle" font-family="P" font-weight="700" font-size="18" fill="{GD}">{lab}</text>'
    return f'<svg viewBox="0 0 640 360" xmlns="http://www.w3.org/2000/svg"><rect width="640" height="360" fill="{bg}"/>{inner}{e}{l}</svg>'
def tx(t,x,y,s=30,c=WH,w=700,a='middle',glow=True):
    f=f' style="filter:drop-shadow(0 0 8px #7FA6FF)"' if glow else ''
    return f'<text x="{x}" y="{y}" text-anchor="{a}" font-family="P" font-weight="{w}" font-size="{s}" fill="{c}"{f}>{t}</text>'
def mark(x,y,h,c=WH):
    k=h/495
    return f'<g transform="translate({x} {y}) scale({k}) translate(-329 -327.5)"><path d="{LT}" fill="{c}"/><path d="{LT}" fill="{c}" transform="rotate(180 329 327.5)"/></g>'
