def shop(open_=False):
    o=f'<rect x="0" y="300" width="640" height="60" fill="#0d2f66"/><rect x="150" y="70" width="340" height="230" fill="{CR}"/>'
    o+=''.join(f'<rect x="{150+i*34}" y="70" width="34" height="46" fill="{[BL,WH][i%2]}"/>' for i in range(10))
    o+=f'<rect x="176" y="126" width="288" height="52" rx="8" fill="{NV}"/>'+mark(206,152,34)+tx('Devdha',330,163,30,WH,800,'middle',False)
    o+=f'<rect x="176" y="196" width="130" height="104" rx="6" fill="{LB}"/><path d="M190 270 h30 M240 250 h50" stroke="{BL}" stroke-width="10" stroke-linecap="round"/>'
    if open_:o+=f'<rect x="334" y="196" width="130" height="104" rx="6" fill="{GD}"/><rect x="346" y="212" width="106" height="88" fill="{GL}"/><path d="M360 296 v-40 h20 v40 M400 296 v-52 h18 v52" stroke="{CO}" stroke-width="10"/>'
    else:o+=f'<rect x="334" y="196" width="130" height="104" rx="6" fill="{BL}"/><circle cx="446" cy="250" r="5" fill="{GD}"/>'
    return o
