def card(s):
    k,sc,t,d,m=s
    return f'<div class="vc"><div class="vimg">{F[k]}</div><div class="vh"><b>{k}</b> · {sc} · {t}</div><div class="vb">{d}</div><div class="vm">Motion: {m}</div></div>'
def page(t,sub,b):return f'<div class="pg"><div class="top"><h2>{t}</h2><small>{sub}</small></div>{b}</div>'
def tbl(h,rows):return '<table class="wide"><tr>'+''.join(f'<th>{x}</th>' for x in h)+'</tr>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in r)+'</tr>' for r in rows)+'</table>'
